<?php require_once __DIR__.'/includes/auth.php';require_login();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=db()->prepare('SELECT a.*,q.title,q.show_score FROM attempts a JOIN quizzes q ON q.id=a.quiz_id WHERE a.id=? AND a.user_id=? AND a.submitted_at IS NOT NULL');$s->execute([$id,user()['id']]);$a=$s->fetch();if(!$a)redirect('index.php');$pct=$a['max_score']>0?round($a['score']/$a['max_score']*100):0;$pageTitle='Resultado · QMAX';require __DIR__.'/includes/header.php'; ?>
<section class="result-card"><div class="confetti">✦</div><div class="result-ring" style="--score:<?= (int)$pct ?>"><div><strong><?= (int)$pct ?>%</strong><span>aproveitamento</span></div></div><div class="eyebrow">DESAFIO CONCLUÍDO</div><h1><?= e($a['title']) ?></h1><p>Resposta registrada com sucesso em nome de <strong><?= e(user()['name']) ?></strong>.</p><?php if($a['show_score']): ?><div class="result-stats"><div><strong><?= e((string)$a['score']) ?></strong><span>pontos</span></div><div><strong><?= e((string)$a['max_score']) ?></strong><span>máximo</span></div><div><strong><?= date('d/m/Y',strtotime($a['submitted_at'])) ?></strong><span>concluído</span></div></div><?php endif; ?><a class="button" href="<?= e(url()) ?>">Voltar aos quizzes</a></section>
<?php require __DIR__.'/includes/footer.php'; ?>

